package com.braseiro.dnd5e;
import org.json.JSONArray;import org.json.JSONObject;import java.util.*;
/** Compiled-first statblock registry. Combat readiness requires an explicitly source-bound mechanical record. */
public final class CompiledStatblockEngine{
 private CompiledStatblockEngine(){} private static final Map<String,JSONObject> REG=new LinkedHashMap<>();
 /** Legacy entrypoint retained for compatibility, but now enforces the same authority contract. */
 public static synchronized JSONObject register(JSONObject raw){return registerAuthorized(raw);}
 public static JSONObject authorityCheck(JSONObject raw){try{JSONObject s=copy(raw);validate(s);validateAuthority(s);return new JSONObject().put("id",s.optString("id")).put("authorized",true).put("authority","authorized_compiled_statblock");}catch(Exception e){JSONObject blocked=new JSONObject();try{return blocked.put("id",raw==null?"":raw.optString("id")).put("authorized",false).put("authority","blocked_statblock_authority");}catch(Exception ignored){return blocked;}}}

 public static synchronized JSONObject registerAuthorized(JSONObject raw){/*BR_JSON_WRAP_106*/try{JSONObject s=copy(raw);validate(s);validateAuthority(s);String id=s.optString("id").trim();int revision=s.optInt("revision",1);if(revision<1)revision=1;s.put("revision",revision);JSONObject old=REG.get(id);int oldRevision=old==null?0:old.optInt("revision",1);if(old!=null&&revision<oldRevision)throw new IllegalArgumentException("statblock revision obsoleta");boolean sameSource=old!=null&&norm(old.optString("source_book")).equals(norm(s.optString("source_book")));if(old!=null&&sameSource&&revision==oldRevision&&!canonical(old).equals(canonical(s)))throw new IllegalArgumentException("conflito de statblock na mesma revisão");s.put("mechanics_authority","authorized_compiled_statblock");REG.put(id,s);return copy(s);}catch(RuntimeException __brJsonRuntime106){throw __brJsonRuntime106;}catch(Exception __brJsonChecked106){throw new IllegalStateException(__brJsonChecked106);}}
 public static synchronized boolean has(String id){return id!=null&&REG.containsKey(id.trim());}
 public static synchronized JSONObject get(String id){JSONObject s=id==null?null:REG.get(id.trim());return copy(s);}
 public static JSONObject completeness(JSONObject s){/*BR_JSON_WRAP_106*/try{JSONObject r=new JSONObject();if(s==null)return r.put("tier","invalid").put("full",false);JSONArray missing=new JSONArray();String[] obj={"movement","abilities","senses"};for(String k:obj)if(s.optJSONObject(k)==null)missing.put(k);if(s.optJSONArray("traits")==null)missing.put("traits");if(s.optJSONArray("actions")==null||(s.optJSONArray("actions").length()==0&&!s.optBoolean("source_actionless",false)))missing.put("actions");boolean tactical=missing.length()==0;boolean full=tactical&&s.optBoolean("full_statblock_claim",false);return r.put("tier",full?"full_runtime":(tactical?"tactical_runtime":"combat_core")).put("full",full).put("tactical",tactical).put("missing",missing).put("missing_count",missing.length());}catch(RuntimeException __brJsonRuntime106){throw __brJsonRuntime106;}catch(Exception __brJsonChecked106){throw new IllegalStateException(__brJsonChecked106);}}
 public static synchronized JSONObject runtimeProfile(String id){/*BR_JSON_WRAP_106*/try{JSONObject s=get(id);if(s.length()==0)return new JSONObject().put("found",false).put("id",id);JSONObject c=completeness(s);return new JSONObject().put("found",true).put("id",id).put("armor_class",s.optInt("armor_class")).put("hit_points",s.optInt("hit_points")).put("challenge_rating",s.optDouble("challenge_rating",0d)).put("actions",s.optJSONArray("actions")).put("movement",s.optJSONObject("movement")).put("abilities",s.optJSONObject("abilities")).put("senses",s.optJSONObject("senses")).put("traits",s.optJSONArray("traits")).put("multiattack",s.optJSONObject("multiattack")).put("special_actions",s.optJSONArray("special_actions")).put("resistances",s.optString("resistances",s.optString("damage_resistances"))).put("vulnerabilities",s.optString("vulnerabilities",s.optString("damage_vulnerabilities"))).put("immunities",s.optString("immunities",s.optString("damage_immunities"))).put("condition_immunities",s.optString("condition_immunities")).put("saving_throws",s.optJSONObject("saving_throws")).put("completeness",c).put("full_statblock_claim",c.optBoolean("full"));}catch(RuntimeException __brJsonRuntime106){throw __brJsonRuntime106;}catch(Exception __brJsonChecked106){throw new IllegalStateException(__brJsonChecked106);}}
 public static synchronized JSONArray ids(){JSONArray a=new JSONArray();for(String k:REG.keySet())a.put(k);return a;}
 public static synchronized JSONObject restoreReplacing(JSONObject snapshot){REG.clear();return restore(snapshot);}
 public static synchronized JSONObject snapshot(){JSONObject o=new JSONObject();JSONArray a=new JSONArray();try{for(JSONObject x:REG.values())a.put(copy(x));o.put("schema","compiled_statblocks_v1").put("records",a).put("count",a.length());}catch(Exception ignored){}return o;}
 public static synchronized JSONObject restore(JSONObject snapshot){JSONObject r=new JSONObject();int restored=0,blocked=0;try{if(snapshot==null||!"compiled_statblocks_v1".equals(snapshot.optString("schema")))return r.put("restored",0).put("blocked",true).put("authority","blocked_invalid_snapshot_schema");JSONArray a=snapshot.optJSONArray("records");if(a==null)a=new JSONArray();for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x==null){blocked++;continue;}try{registerAuthorized(x);restored++;}catch(Exception bad){blocked++;}}return r.put("restored",restored).put("blocked_records",blocked).put("authority",blocked==0?"authorized_snapshot_restore":"partial_snapshot_restore");}catch(Exception e){try{return r.put("restored",restored).put("blocked_records",blocked+1).put("authority","blocked_snapshot_restore_error");}catch(Exception ignored){return r;}}}
 public static JSONObject bindActor(JSONObject actor){JSONObject a=copy(actor);try{String id=a.optString("statblock_id").trim();boolean ok=has(id);a.put("combat_ready",ok);a.put("mechanics_authority",ok?"authorized_compiled_statblock":"blocked_no_authorized_compiled_statblock");if(ok){JSONObject s=get(id);a.put("statblock_source",s.optString("source_book")).put("statblock_revision",s.optInt("revision",1));}}catch(Exception ignored){}return a;}
 public static void validate(JSONObject s){if(s==null)throw new IllegalArgumentException("statblock ausente");String id=s.optString("id").trim();if(id.length()<3)throw new IllegalArgumentException("statblock id inválido");if(s.optString("source_book").trim().isEmpty())throw new IllegalArgumentException("fonte mecânica obrigatória");if(!s.has("armor_class")||s.optInt("armor_class",0)<=0)throw new IllegalArgumentException("CA inválida");if(!s.has("hit_points")||s.optInt("hit_points",0)<=0)throw new IllegalArgumentException("PV inválido");if(s.optString("creature_type").trim().isEmpty())throw new IllegalArgumentException("tipo obrigatório");if(!s.has("actions"))throw new IllegalArgumentException("ações compiladas obrigatórias");}
 private static void validateAuthority(JSONObject s){JSONObject b=s.optJSONObject("mechanical_basis");if(b==null)throw new IllegalArgumentException("mechanical_basis obrigatório");String id=s.optString("id").trim(),book=s.optString("source_book").trim();String type=b.optString("source_type").trim(),kind=b.optString("content_kind").trim(),name=b.optString("content_name").trim(),basisBook=b.optString("source_book").trim(),loc=b.optString("source_locator").trim();if(!"compiled_statblock".equals(type))throw new IllegalArgumentException("source_type inválido");if(!"statblock".equals(kind))throw new IllegalArgumentException("content_kind inválido");if(!norm(id).equals(norm(name)))throw new IllegalArgumentException("content_name não corresponde ao statblock");if(!book.equals(basisBook))throw new IllegalArgumentException("source_book não corresponde à base");if(loc.isEmpty())throw new IllegalArgumentException("source_locator obrigatório");}
 private static String canonical(JSONObject s){JSONObject c=copy(s);c.remove("mechanics_authority");return c.toString();}
 private static String norm(String x){return x==null?"":x.trim().toLowerCase(Locale.ROOT);}private static JSONObject copy(JSONObject o){try{return o==null?new JSONObject():new JSONObject(o.toString());}catch(Exception e){return new JSONObject();}}
}
